using System;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.Video;

/// <summary>Installs native opening references after formal UGUI prefab generation.</summary>
[InitializeOnLoad]
public static class MiniwowOpeningSetup
{
    /// <summary>Explicit editor request and evidence directory.</summary>
    private const string toolsPath = "../tools/opening/";

    /// <summary>Product opening prefab generated by UnityCLI.</summary>
    private const string prefabPath = "Assets/Data/Widgets/Home/UIHomeOpening.prefab";

    /// <summary>Registers idle-time authoring without entering the game.</summary>
    static MiniwowOpeningSetup()
    {
        EditorApplication.update += Poll;
    }

    /// <summary>Processes only an explicit installation request in edit mode.</summary>
    private static void Poll()
    {
        string request = toolsPath + "install.request";
        if (!File.Exists(request) || EditorApplication.isCompiling || EditorApplication.isUpdating
            || EditorApplication.isPlayingOrWillChangePlaymode)
            return;

        File.Delete(request);
        try
        {
            BindUI();
            BindHome();
            BindScene();
            File.WriteAllText(toolsPath + "install-result.json", "{\"ok\":true}");
        }
        catch (Exception exception)
        {
            File.WriteAllText(toolsPath + "install-result.json", new JObject {
                ["ok"] = false,
                ["error"] = exception.ToString()
            }.ToString());
            Debug.LogException(exception);
        }
    }

    /// <summary>Binds native video and portraits without runtime object searches.</summary>
    private static void BindUI()
    {
        string merchantPath = "Assets/Data/Widgets/Common/Icons/Conversation_auction.png";
        var importer = (TextureImporter)AssetImporter.GetAtPath(merchantPath);
        importer.textureType = TextureImporterType.Sprite;
        importer.SaveAndReimport();
        var root = PrefabUtility.LoadPrefabContents(prefabPath);
        try
        {
            var nodes = root.GetComponentsInChildren<Transform>(true).ToDictionary(item => item.name);
            Font font = AssetDatabase.LoadAssetAtPath<Font>("Assets/Data/Widgets/Common/Fonts/fangzhenglanting.ttf");
            foreach (Text text in root.GetComponentsInChildren<Text>(true))
            {
                text.font = font;
                text.raycastTarget = false;
                text.horizontalOverflow = HorizontalWrapMode.Wrap;
                text.verticalOverflow = VerticalWrapMode.Truncate;
                if (text.name == "Dialogue")
                {
                    text.fontSize = 32;
                    text.alignment = TextAnchor.MiddleLeft;
                }
                if (text.name == "Dialogue" || text.name == "Speaker" || text.name.EndsWith("Label")
                    || text.name == "ConfirmText")
                    text.color = new Color(0.2f, 0.12f, 0.06f);
            }

            foreach (Image image in root.GetComponentsInChildren<Image>(true))
            {
                image.raycastTarget = image.GetComponent<Button>() != null
                    || image.name == "MovieVisible" || image.name == "ConfirmVisible"
                    || image.name == "DialogueVisible";
                if (image.sprite == null)
                    image.color = image.GetComponent<Button>() != null
                        ? new Color(0.46f, 0.27f, 0.1f, 1f) : new Color(0.12f, 0.1f, 0.08f, 0.94f);
            }

            nodes["MovieVisible"].GetComponent<Image>().color = Color.black;
            nodes["ConfirmVisible"].GetComponent<Image>().color = new Color(0f, 0f, 0f, 0.85f);
            var screenObject = nodes["VideoScreen"].gameObject;
            var imageComponent = screenObject.GetComponent<Image>();
            if (imageComponent)
                UnityEngine.Object.DestroyImmediate(imageComponent);

            var screen = screenObject.GetComponent<RawImage>();
            if (!screen)
                screen = screenObject.AddComponent<RawImage>();
            screen.raycastTarget = false;
            var movie = root.GetComponent<VideoPlayer>();
            if (!movie)
                movie = root.AddComponent<VideoPlayer>();
            var config = JObject.Parse(File.ReadAllText("Assets/Data/Jsons/Excels/HomeOpeningConfig.bytes"))["data"]["1"];
            movie.clip = AssetDatabase.LoadAssetAtPath<VideoClip>((string)config["VideoPath"]);
            movie.playOnAwake = false;
            movie.isLooping = false;
            movie.renderMode = VideoRenderMode.RenderTexture;
            movie.aspectRatio = VideoAspectRatio.FitInside;
            movie.audioOutputMode = VideoAudioOutputMode.Direct;
            var fit = screen.GetComponent<AspectRatioFitter>();
            if (!fit)
                fit = screen.gameObject.AddComponent<AspectRatioFitter>();

            fit.aspectMode = AspectRatioFitter.AspectMode.FitInParent;
            fit.aspectRatio = movie.clip.width / (float)movie.clip.height;
            var music = root.GetComponent<AudioSource>();
            if (!music)
                music = root.AddComponent<AudioSource>();

            music.playOnAwake = false;
            music.loop = true;
            music.clip = AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Data/Widgets/Home/Opening/start_game.wav");
            var serialized = new SerializedObject(root.GetComponent<UIHomeOpening>());
            serialized.FindProperty("music").objectReferenceValue = music;
            serialized.FindProperty("movie").objectReferenceValue = movie;
            serialized.FindProperty("screen").objectReferenceValue = screen;
            serialized.FindProperty("portrait").objectReferenceValue = nodes["Portrait"].GetComponent<Image>();
            serialized.FindProperty("priest").objectReferenceValue = AssetDatabase.LoadAssetAtPath<Sprite>(
                "Assets/Data/Widgets/Common/Icons/Conversation_priest.png");
            serialized.FindProperty("merchant").objectReferenceValue = AssetDatabase.LoadAssetAtPath<Sprite>(merchantPath);
            serialized.ApplyModifiedPropertiesWithoutUndo();
            foreach (string name in new[] { "ConfirmVisible", "ErrorVisible", "MovieVisible", "DialogueVisible",
                "ObjectiveVisible", "RescueVisible", "ClaimVisible" })
                nodes[name].gameObject.SetActive(false);

            Stretch((RectTransform)root.transform);
            PrefabUtility.SaveAsPrefabAsset(root, prefabPath);
        }
        finally
        {
            PrefabUtility.UnloadPrefabContents(root);
        }
    }

    /// <summary>Connects the existing task bar and HUD groups to opening presentation.</summary>
    private static void BindHome()
    {
        const string path = "Assets/Data/Widgets/Home/UIHome.prefab";
        var root = PrefabUtility.LoadPrefabContents(path);
        try
        {
            var nodes = root.GetComponentsInChildren<Transform>(true);
            var serialized = new SerializedObject(root.GetComponent<UIHome>());
            string[] hidden = { "Entries", "MapClick", "ChatClick", "RightRail", "BottomPlate" };
            var targets = serialized.FindProperty("openingHidden");
            targets.arraySize = hidden.Length;
            for (int index = 0; index < hidden.Length; index++)
                targets.GetArrayElementAtIndex(index).objectReferenceValue = nodes.Single(n => n.name == hidden[index]).gameObject;

            serialized.FindProperty("taskControl").objectReferenceValue = nodes.Single(n => n.name == "TaskClick").gameObject;
            serialized.ApplyModifiedPropertiesWithoutUndo();
            PrefabUtility.SaveAsPrefabAsset(root, path);
        }
        finally
        {
            PrefabUtility.UnloadPrefabContents(root);
        }
    }

    /// <summary>Adds only opening effects and bindings to the existing authored scene.</summary>
    private static void BindScene()
    {
        var scenes = JObject.Parse(File.ReadAllText("Assets/Data/Jsons/Excels/SceneConfig.bytes"));
        var scene = EditorSceneManager.OpenScene((string)scenes["data"]["10002"]["Path"]);
        var home = scene.GetRootGameObjects().Select(root => root.GetComponent<HomeScene>()).Single(item => item);
        var opening = home.GetComponent<HomeOpeningScene>();
        if (!opening)
            opening = home.gameObject.AddComponent<HomeOpeningScene>();
        var existing = home.transform.Find("OpeningPresentation");
        if (existing)
            UnityEngine.Object.DestroyImmediate(existing.gameObject);

        var container = new GameObject("OpeningPresentation");
        container.transform.SetParent(home.transform, false);
        var texture = AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Data/Scenes/Home/Opening/fire.png");
        const string materialPath = "Assets/Data/Scenes/Home/Opening/fire.mat";
        var material = AssetDatabase.LoadAssetAtPath<Material>(materialPath);
        if (!material)
        {
            material = new Material(Shader.Find("Particles/Standard Unlit"));
            material.SetFloat("_Mode", 1);
            material.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
            material.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.One);
            material.SetInt("_ZWrite", 0);
            material.renderQueue = 3000;
            AssetDatabase.CreateAsset(material, materialPath);
        }

        material.mainTexture = texture;
        var fire = new GameObject("AuctionFire");
        fire.transform.SetParent(container.transform, false);
        fire.transform.position = new Vector3(-8.7f, 35.4f, 8.4f);
        var particles = fire.AddComponent<ParticleSystem>();
        particles.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
        var main = particles.main;
        main.startLifetime = 1.2f;
        main.startSpeed = 0.7f;
        main.startSize = 3f;
        main.maxParticles = 35;
        var emission = particles.emission;
        emission.rateOverTime = 12f;
        var shape = particles.shape;
        shape.shapeType = ParticleSystemShapeType.Box;
        shape.scale = new Vector3(2.5f, 0.1f, 1.5f);
        var sheet = particles.textureSheetAnimation;
        sheet.enabled = true;
        sheet.numTilesX = 4;
        sheet.numTilesY = 4;
        particles.GetComponent<ParticleSystemRenderer>().sharedMaterial = material;
        var marker = new GameObject("Destination");
        marker.transform.SetParent(container.transform, false);
        var ring = marker.AddComponent<LineRenderer>();
        ring.useWorldSpace = false;
        ring.loop = true;
        ring.widthMultiplier = 0.12f;
        ring.positionCount = 48;
        const string markerMaterialPath = "Assets/Data/Scenes/Home/Opening/marker.mat";
        var markerMaterial = AssetDatabase.LoadAssetAtPath<Material>(markerMaterialPath);
        if (!markerMaterial)
        {
            markerMaterial = new Material(Shader.Find("Sprites/Default"));
            AssetDatabase.CreateAsset(markerMaterial, markerMaterialPath);
        }

        ring.sharedMaterial = markerMaterial;
        ring.startColor = ring.endColor = new Color(1f, 0.8f, 0.15f);
        for (int index = 0; index < 48; index++)
        {
            float angle = index * Mathf.PI * 2f / 48f;
            ring.SetPosition(index, new Vector3(Mathf.Cos(angle), 0.15f, Mathf.Sin(angle)));
        }

        var streamObject = new GameObject("WaterStream");
        streamObject.transform.SetParent(container.transform, false);
        var stream = streamObject.AddComponent<LineRenderer>();
        stream.positionCount = 20;
        stream.widthMultiplier = 0.16f;
        stream.sharedMaterial = markerMaterial;
        stream.startColor = stream.endColor = new Color(0.3f, 0.85f, 1f, 0.85f);
        streamObject.SetActive(false);
        var serialized = new SerializedObject(opening);
        serialized.FindProperty("waterStream").objectReferenceValue = stream;
        serialized.FindProperty("auctionFire").objectReferenceValue = fire;
        serialized.FindProperty("destination").objectReferenceValue = marker.transform;
        serialized.ApplyModifiedPropertiesWithoutUndo();
        serialized = new SerializedObject(home);
        serialized.FindProperty("openingScene").objectReferenceValue = opening;
        serialized.ApplyModifiedPropertiesWithoutUndo();
        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        AssetDatabase.SaveAssets();
    }

    /// <summary>Preserves the required fullscreen root anchors.</summary>
    /// <param name="rect">The root transform.</param>
    private static void Stretch(RectTransform rect)
    {
        rect.anchorMin = Vector2.zero;
        rect.anchorMax = Vector2.one;
        rect.offsetMin = Vector2.zero;
        rect.offsetMax = Vector2.zero;
    }
}
